def isi_tahun_pelajaran(apps, schema_editor):
    AcademicYear = apps.get_model('akademik', 'AcademicYear')
    Subject = apps.get_model('akademik', 'Subject')
    HomeroomNote = apps.get_model('akademik', 'HomeroomNote')
    Extracurricular = apps.get_model('akademik', 'Extracurricular')

    tahun = (
        AcademicYear.objects.filter(aktif=True).first()
        or AcademicYear.objects.first()
    )
    if tahun is None:
        return
    Subject.objects.filter(academic_year__isnull=True).update(academic_year=tahun)
    for model in (HomeroomNote, Extracurricular):
        for obj in model.objects.filter(academic_year__isnull=True).select_related('semester'):
            obj.academic_year = obj.semester.academic_year
            obj.save(update_fields=['academic_year'])


